    const string Password="TemporaryTournament2026!";static int passed;static string group="Fixture authentication";static readonly Dictionary<string,int> groups=[];
    static void Check(bool value,string name){if(!value)throw new Exception("FAIL: "+name);passed++;groups[group]=groups.GetValueOrDefault(group)+1;Console.WriteLine("PASS: "+name);}
    static async Task<JsonElement> Json(HttpResponseMessage r)=>JsonDocument.Parse(await r.Content.ReadAsStringAsync()).RootElement.Clone();
    static async Task<string> Token(HttpClient c){var s=await c.GetStringAsync("/index.html");return JsonDocument.Parse(Regex.Match(s,"<script id=\"kicks-auth-state\" type=\"application/json\">(.*?)</script>",RegexOptions.Singleline).Groups[1].Value).RootElement.GetProperty("token").GetString()!;}
    static async Task<HttpResponseMessage> Post(HttpClient c,string url,Dictionary<string,string>? data=null,bool csrf=true){data??=[];if(csrf)data["__RequestVerificationToken"]=await Token(c);return await c.PostAsync(url,new FormUrlEncodedContent(data));}
    static async Task Expect(Task<HttpResponseMessage> action,HttpStatusCode status,string name){using var r=await action;Check(r.StatusCode==status,name+" ("+(int)r.StatusCode+")");if(r.StatusCode!=status)Console.WriteLine(await r.Content.ReadAsStringAsync());}
    static async Task<JsonElement> Detail(HttpClient c,int id){using var r=await c.GetAsync("/api/tournaments/"+id);if(!r.IsSuccessStatusCode)throw new Exception("Details failed "+await r.Content.ReadAsStringAsync());return await Json(r);}
    static string Version(JsonElement t)=>t.GetProperty("version").GetString()!;
    static JsonElement Match(JsonElement t,int index=0)=>t.GetProperty("matches")[index];
    static Dictionary<string,string> V(JsonElement t)=>new(){{"Version",Version(t)}};
    static async Task<string> Quote(HttpClient c,Dictionary<string,string> input){using var r=await Post(c,"/tournaments/quote",input);if(!r.IsSuccessStatusCode)throw new Exception("Quote failed "+await r.Content.ReadAsStringAsync());return(await Json(r)).GetProperty("token").GetString()!;}
    static async Task<int> Create(HttpClient c,Dictionary<string,string> input){var q=await Quote(c,input);using var r=await Post(c,"/tournaments",new(){{"Token",q}});if(!r.IsSuccessStatusCode)throw new Exception("Creation failed "+await r.Content.ReadAsStringAsync());return(await Json(r)).GetProperty("id").GetInt32();}
    static Dictionary<string,string> Input(int field,DateOnly day,int capacity=2,decimal fee=0m)=>new(){{"FieldId",field.ToString()},{"Name","SQL Tournament"},{"Description","Isolated tournament fixture"},{"RegistrationOpensLocal",DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(3)).AddHours(-1).ToString("yyyy-MM-ddTHH:mm")},{"RegistrationClosesLocal",day.ToDateTime(new TimeOnly(12,0)).ToString("yyyy-MM-ddTHH:mm")},{"StartsLocal",day.ToDateTime(new TimeOnly(13,0)).ToString("yyyy-MM-ddTHH:mm")},{"EndsLocal",day.AddDays(50).ToDateTime(new TimeOnly(23,0)).ToString("yyyy-MM-ddTHH:mm")},{"MatchDurationMinutes","60"},{"Capacity",capacity.ToString()},{"EntryFee",fee.ToString(System.Globalization.CultureInfo.InvariantCulture)},{"Prize","Friendly trophy"},{"Level","All levels"},{"System","Single elimination"}};
    static Dictionary<string,string> Slot(JsonElement m,DateOnly day,int hour=17,int duration=60)=>new(){{"Version",Version(m)},{"Date",day.ToString("yyyy-MM-dd")},{"Hour",hour.ToString()},{"DurationMinutes",duration.ToString()}};
    static string Url(int t,JsonElement m,string action)=>$"/tournaments/{t}/matches/{m.GetProperty("id").GetInt32()}/{action}";
    static Dictionary<string,string> Score(JsonElement m,int home=2,int away=1)=>new(){{"Version",Version(m)},{"HomeScore",home.ToString()},{"AwayScore",away.ToString()}};
    static async Task<HttpResponseMessage[]> Race((HttpClient Client,string Url,Dictionary<string,string> Data) a,(HttpClient Client,string Url,Dictionary<string,string> Data)b)
    {
        var ta=await Token(a.Client);var tb=await Token(b.Client);var gate=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);
        async Task<HttpResponseMessage> Fire((HttpClient Client,string Url,Dictionary<string,string> Data)x,string token){await gate.Task;x.Data["__RequestVerificationToken"]=token;return await x.Client.PostAsync(x.Url,new FormUrlEncodedContent(x.Data));}
        var ar=Fire(a,ta);var br=Fire(b,tb);gate.SetResult();return await Task.WhenAll(ar,br);
    }
    sealed record Data(User Owner,User OtherOwner,User Outsider,User Member,User Lead,User[] Captains,int Field,int OtherField,int[] Teams);
    static async Task<User> Account(UserManager<User> users,string marker,string suffix,string role){var u=new User{Email=marker+"-"+suffix+"@example.test",UserName=marker+"-"+suffix+"@example.test",FullName="Tournament test "+suffix,Status="Active",LockoutEnabled=true};if(!(await users.CreateAsync(u,Password)).Succeeded||!(await users.AddToRoleAsync(u,role)).Succeeded)throw new Exception("Fixture account failed");return u;}
    static async Task<Data> Setup(KicksDbContext db,UserManager<User> users,string marker)
    {
        var owner=await Account(users,marker,"owner","owner");var other=await Account(users,marker,"other-owner","owner");var outside=await Account(users,marker,"outsider","player");var member=await Account(users,marker,"member","player");var lead=await Account(users,marker,"lead","player");var captains=new List<User>();var teams=new List<Team>();
        for(var i=1;i<=9;i++){var u=await Account(users,marker,"captain"+i,"player");captains.Add(u);var team=new Team{CaptainId=u.Id,Name="Squad "+i+" "+marker[^8..],City="Amman",Area="Test",Bio="Isolated tournament squad",Initials="T"+i};teams.Add(team);db.Teams.Add(team);}
        var f=new Field{OwnerId=owner.Id,Name=marker+" pitch",City="Amman",Area="Test",Description="Isolated field",HourlyPrice=0};var f2=new Field{OwnerId=other.Id,Name=marker+" other",City="Amman",Area="Test",Description="Isolated field",HourlyPrice=0};db.Fields.AddRange(f,f2);await db.SaveChangesAsync();foreach(var team in teams)db.TeamMembers.Add(new(){TeamId=team.Id,UserId=team.CaptainId});db.TeamMembers.AddRange(new TeamMember{TeamId=teams[0].Id,UserId=member.Id},new TeamMember{TeamId=teams[8].Id,UserId=lead.Id});await db.SaveChangesAsync();return new(owner,other,outside,member,lead,captains.ToArray(),f.Id,f2.Id,teams.Select(t=>t.Id).ToArray());
    }
    public static async Task Fixture(string marker,string action)
    {
        if(!Regex.IsMatch(marker,"^tournament-browser-[a-f0-9]{32}$"))throw new Exception("Invalid isolated marker");using var factory=new AuthFactory();using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<KicksDbContext>();
        if(action=="cleanup"){await Cleanup(db,marker);return;}
        if(action=="ended")
        {
            // Explicit isolated clock fixture: retain generated teams/fixtures, shift only this run's scheduled intervals to ended historical dates.
            var ids=await db.Tournaments.Where(t=>t.Name.StartsWith(marker)&&t.Field.Owner.Email!.StartsWith(marker+"-")).Select(t=>t.Id).ToListAsync();var start=new DateTimeOffset(DateTimeOffset.UtcNow.ToOffset(TimeSpan.FromHours(3)).Date.AddDays(-3).AddHours(13),TimeSpan.FromHours(3));
            foreach(var id in ids){await db.Tournaments.Where(t=>t.Id==id).ExecuteUpdateAsync(s=>s.SetProperty(t=>t.RegistrationOpensAt,start.AddDays(-3)).SetProperty(t=>t.RegistrationClosesAt,start.AddDays(-1)).SetProperty(t=>t.StartsAt,start).SetProperty(t=>t.DurationMinutes,144000));var matches=await db.TournamentMatches.Where(m=>m.TournamentId==id&&m.Status=="Scheduled").OrderBy(m=>m.Id).ToListAsync();for(var i=0;i<matches.Count;i++)matches[i].StartsAt=start.AddDays(matches[i].RoundNumber-1).AddHours((matches[i].MatchNumber-1)*2);await db.SaveChangesAsync();}return;
        }
        var d=await Setup(db,scope.ServiceProvider.GetRequiredService<UserManager<User>>(),marker);Console.WriteLine(JsonSerializer.Serialize(new{fieldId=d.Field,otherFieldId=d.OtherField,teamIds=d.Teams}));
    }
