    static async Task Cleanup(KicksDbContext db,string marker)
    {
        db.ChangeTracker.Clear();var users=await db.Users.Where(u=>u.Email!.StartsWith(marker+"-")).Select(u=>u.Id).ToListAsync();var fields=await db.Fields.Where(f=>users.Contains(f.OwnerId)).Select(f=>f.Id).ToListAsync();var teams=await db.Teams.Where(t=>users.Contains(t.CaptainId)).Select(t=>t.Id).ToListAsync();var tournaments=await db.Tournaments.Where(t=>fields.Contains(t.FieldId)&&users.Contains(t.CreatedBy)).Select(t=>t.Id).ToListAsync();var regs=await db.TournamentRegistrations.Where(r=>tournaments.Contains(r.TournamentId)).Select(r=>r.Id).ToListAsync();var games=await db.OpenGames.Where(g=>fields.Contains(g.FieldId)).Select(g=>g.Id).ToListAsync();var challenges=await db.Challenges.Where(c=>teams.Contains(c.HostTeamId)&&users.Contains(c.PostedBy)).Select(c=>c.Id).ToListAsync();var bookings=await db.Bookings.Where(b=>fields.Contains(b.FieldId)&&users.Contains(b.UserId)).Select(b=>b.Id).ToListAsync();await using var tx=await db.Database.BeginTransactionAsync();await db.TournamentMatchSlots.Where(s=>tournaments.Contains(s.TournamentId)).ExecuteDeleteAsync();await db.TournamentMatches.Where(m=>tournaments.Contains(m.TournamentId)).ExecuteDeleteAsync();await db.TournamentDrawEntries.Where(e=>tournaments.Contains(e.TournamentId)).ExecuteDeleteAsync();await db.RegistrationPlayers.Where(p=>regs.Contains(p.RegistrationId)).ExecuteDeleteAsync();await db.TournamentRegistrations.Where(r=>regs.Contains(r.Id)).ExecuteDeleteAsync();await db.Tournaments.Where(t=>tournaments.Contains(t.Id)).ExecuteDeleteAsync();await db.BookingTeams.Where(t=>bookings.Contains(t.BookingId)).ExecuteDeleteAsync();await db.Bookings.Where(b=>bookings.Contains(b.Id)).ExecuteDeleteAsync();await db.ChallengeRequests.Where(r=>challenges.Contains(r.ChallengeId)).ExecuteDeleteAsync();await db.Challenges.Where(c=>challenges.Contains(c.Id)).ExecuteDeleteAsync();await db.GameParticipants.Where(p=>games.Contains(p.GameId)).ExecuteDeleteAsync();await db.OpenGames.Where(g=>games.Contains(g.Id)).ExecuteDeleteAsync();await db.TeamRequests.Where(r=>teams.Contains(r.TeamId)&&users.Contains(r.UserId)).ExecuteDeleteAsync();await db.TeamMembers.Where(m=>teams.Contains(m.TeamId)&&users.Contains(m.UserId)).ExecuteDeleteAsync();await db.TeamRecruitingPositions.Where(p=>teams.Contains(p.TeamId)).ExecuteDeleteAsync();await db.Teams.Where(t=>teams.Contains(t.Id)).ExecuteDeleteAsync();await db.FieldImages.Where(i=>fields.Contains(i.FieldId)).ExecuteDeleteAsync();await db.FieldAmenities.Where(i=>fields.Contains(i.FieldId)).ExecuteDeleteAsync();await db.Fields.Where(f=>fields.Contains(f.Id)).ExecuteDeleteAsync();await db.UserRoles.Where(r=>users.Contains(r.UserId)).ExecuteDeleteAsync();await db.UserClaims.Where(r=>users.Contains(r.UserId)).ExecuteDeleteAsync();await db.UserLogins.Where(r=>users.Contains(r.UserId)).ExecuteDeleteAsync();await db.UserTokens.Where(r=>users.Contains(r.UserId)).ExecuteDeleteAsync();await db.Users.Where(u=>users.Contains(u.Id)).ExecuteDeleteAsync();await tx.CommitAsync();
    }
